/**
 * Chess piece artwork.
 *
 * Seven sets. Six are externally sourced and bundled in `assets/pieces.svg`
 * (generated by tools/fetch-pieces.mjs); the seventh, "Pocket", was drawn for
 * this project and is defined inline below.
 *
 * All six external sets are permissively licensed — see assets/pieces/CREDITS.md
 * for authors and terms. Cburnett in particular is taken from Wikimedia Commons
 * under its BSD 3-clause option rather than from Lichess, which redistributes
 * the same artwork under GPLv2+.
 *
 * Pocket is kept for two reasons beyond taste: it is available before the
 * sprite file loads, and it is the only set whose colours come from CSS custom
 * properties, so it is the one that follows board themes and the high-contrast
 * accessibility theme. External sets have their colours baked in.
 *
 * Symbol ids are `<set>-<colour><type>`, e.g. `#cburnett-wn`. Pocket's shapes
 * sit on a 45x45 grid with the baseline at y=41 so all six pieces share a footing.
 */

import { getProfile } from '../core/store.js';

export const DEFAULT_SET = 'cburnett';

/**
 * Bundled sets, in the order they appear in Settings.
 * `themeable` marks the set whose colours follow the board theme.
 */
export const PIECE_SETS = [
  {
    id: 'cburnett', name: 'Cburnett', author: 'Colin M.L. Burnett',
    licence: 'BSD 3-clause', blurb: 'The classic Staunton set',
  },
  {
    id: 'pocket', name: 'Pocket', author: 'Drawn for this project',
    licence: 'MIT', blurb: 'Minimal — follows the board theme', themeable: true,
  },
  {
    id: 'chessnut', name: 'Chessnut', author: 'Alexis Luengas',
    licence: 'Apache 2.0', blurb: 'Clean and modern',
  },
  {
    id: 'rhosgfx', name: 'Vector Ranks', author: 'RhosGFX',
    licence: 'CC0 1.0', blurb: 'Warm flat vectors',
  },
  {
    id: 'kiwen-suwi', name: 'Kiwen Suwi', author: 'neverRare',
    licence: 'CC BY 4.0', blurb: 'Soft and rounded',
  },
  {
    id: 'totoy', name: 'Totoy', author: 'Kosal Sen',
    licence: 'CC BY 4.0', blurb: 'Playful and bold',
  },
  {
    id: 'papercut', name: 'Papercut', author: 'Nikolay Anzarov',
    licence: 'CC BY 4.0', blurb: 'Layered paper craft',
  },
];

export function setById(id) {
  return PIECE_SETS.find((s) => s.id === id) || PIECE_SETS.find((s) => s.id === DEFAULT_SET);
}

