function pocketSprite() {
  const symbols = [];
  for (const [type, shape] of Object.entries(POCKET_SHAPES)) {
    for (const colour of ['w', 'b']) {
      symbols.push(
        `<symbol id="pocket-${colour}${type}" viewBox="0 0 45 45">` +
          `<g class="pc pc-${colour}">${shape}</g>` +
        `</symbol>`
      );
    }
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden">${symbols.join('')}</svg>`;
}

// -- active set --------------------------------------------------------------

let activeId = null;

export function activeSetId() {
  if (activeId) return activeId;
  try {
    activeId = getProfile().prefs.pieceSet || DEFAULT_SET;
  } catch {
    activeId = DEFAULT_SET;
  }
  return activeId;
}

export function setActiveSet(id) {
  activeId = setById(id).id;
  return activeId;
}

/** `#cburnett-wn` for the active set. */
export function pieceHref(colour, type) {
  return `#${activeSetId()}-${colour}${type}`;
}

/** Same, for an explicit set — used by the Settings previews. */
export function pieceHrefFor(setId, colour, type) {
  return `#${setById(setId).id}-${colour}${type}`;
}

// -- DOM ---------------------------------------------------------------------

let spritePromise = null;

/**
 * Injects the Pocket set immediately, then loads the bundled external sets.
 *
 * Awaited during boot so the default set is present for the first paint;
 * Pocket going in synchronously means a sprite fetch failure degrades to a
 * playable board rather than an empty one.
 */
export function installSprite(doc = document) {
  if (spritePromise) return spritePromise;

  if (!doc.getElementById('piece-sprite-pocket')) {
    const host = doc.createElement('div');
    host.id = 'piece-sprite-pocket';
    host.setAttribute('aria-hidden', 'true');
    host.innerHTML = pocketSprite();
    doc.body.prepend(host);
  }

  const url = new URL('../../assets/pieces.svg', import.meta.url).href;
  spritePromise = fetch(url)
    .then((res) => {
      if (!res.ok) throw new Error(`piece sprite: HTTP ${res.status}`);
      return res.text();
    })
    .then((svg) => {
      if (doc.getElementById('piece-sprite-external')) return true;
      const host = doc.createElement('div');
      host.id = 'piece-sprite-external';
      host.setAttribute('aria-hidden', 'true');
      host.innerHTML = svg;
      doc.body.prepend(host);
      return true;
    })
    .catch((err) => {
      // Fall back to Pocket rather than rendering an empty board.
      console.warn('Falling back to the Pocket piece set:', err.message);
      setActiveSet('pocket');
      return false;
    });

  return spritePromise;
}

/** An <svg><use> element for a chess.js piece ({ type, color }). */
export function pieceElement(piece, setId) {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('class', 'piece');
  svg.setAttribute('viewBox', '0 0 45 45');
  svg.setAttribute('aria-hidden', 'true');
  const use = document.createElementNS('http://www.w3.org/2000/svg', 'use');
  // A <symbol> carries its own viewBox, so <use> scales each set's native
  // coordinate space (45, 72, 260, 800, 5871…) into this 45x45 viewport.
  use.setAttribute('href', setId
    ? pieceHrefFor(setId, piece.color, piece.type)
    : pieceHref(piece.color, piece.type));
  svg.appendChild(use);
  return svg;
}
